public sealed class InsertTextCommand(Document doc, string text) : ICommand {
    public event EventHandler? CanExecuteChanged { add { } remove { } }
    public bool CanExecute(object? _) => doc.IsEditable;
    public void Execute(object? _) => doc.Insert(text);
    public void Undo() => doc.DeleteLast(text.Length);   // not part of ICommand
}

// non-UI invoker: delegates carry the same request
var history = new List<(Action Do, Action Undo)>();
history.Add((() => doc.Insert(text), () => doc.DeleteLast(text.Length)));
